(() => {
  // Look for all fetch/XHR patterns in scripts
  const scripts = Array.from(document.querySelectorAll('script'));
  const apiCalls = new Set();

  scripts.forEach(s => {
    if (s.textContent) {
      // Find fetch calls
      const fetchMatches = s.textContent.match(/fetch\(['"]([^'"]+)['"]/g);
      if (fetchMatches) fetchMatches.forEach(m => apiCalls.add(m));

      // Find supabase URLs
      const supabaseMatches = s.textContent.match(/supabase\.co[^\s\"'<>]+/g);
      if (supabaseMatches) supabaseMatches.forEach(m => apiCalls.add(m));

      // Find any API URLs
      const apiMatches = s.textContent.match(/https?:\/\/[^\s\"'<>]+api[^\s\"'<>]*/gi);
      if (apiMatches) apiMatches.forEach(m => apiCalls.add(m));
    }
  });

  // Also check inline event handlers and data attributes
  const allElements = Array.from(document.querySelectorAll('*'));
  const dataApis = new Set();
  allElements.forEach(el => {
    for (let attr of el.attributes) {
      if (attr.value.includes('http') && (attr.value.includes('api') || attr.value.includes('supabase'))) {
        dataApis.add(attr.value);
      }
    }
  });

  return JSON.stringify({
    apiCalls: Array.from(apiCalls).slice(0, 50),
    dataApis: Array.from(dataApis).slice(0, 50)
  });
})()
